// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadNunito = makeLoadFont('Nunito');
import { Star, Circle } from "@remotion/shapes";

const { fontFamily: nunitoFamily } = loadNunito();



export type PreschoolTitleProps = Record<string, any>;

const SHAPES_CONFIG = [
  { type: "star", x: 0.15, y: 0.2, s: 1.5, r: 10, points: 5 },
  { type: "circle", x: 0.85, y: 0.25, s: 1, r: -5 },
  { type: "star", x: 0.8, y: 0.8, s: 1.2, r: 15, points: 5 },
  { type: "circle", x: 0.1, y: 0.75, s: 0.8, r: -10 },
  { type: "star", x: 0.5, y: 0.12, s: 0.9, r: 5, points: 6 },
  { type: "circle", x: 0.5, y: 0.88, s: 1.3, r: 20 },
  { type: "star", x: 0.25, y: 0.85, s: 0.7, r: -25, points: 5 },
  { type: "circle", x: 0.75, y: 0.15, s: 0.6, r: 40 },
  { type: "circle", x: 0.25, y: 0.15, s: 0.5, r: 10 },
  { type: "star", x: 0.75, y: 0.85, s: 0.8, r: 5, points: 4 },
];

const PreschoolTitle: React.FC<PreschoolTitleProps> = ({
  backgroundColor = "#D9F4FF",
  transparentBackground = false,
  durationInSeconds = 5,
  titleText = "Carpool Karaoke with Jake and Joey",
  wordColors = ["#FF4B4B", "#FF8F00", "#FFD400", "#8AC926", "#1982C4", "#6A4C93"],
  shapeColors = ["#FFD400", "#1982C4", "#FF4B4B", "#8AC926", "#FF8F00"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;
  const words = titleText.trim().split(/\s+/);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      
      {/* Background Shapes Layer */}
      <AbsoluteFill>
        {SHAPES_CONFIG.map((shape, i) => {
          const shapeScale = spring({
            fps,
            frame: frame - i * 3,
            config: { damping: 10, stiffness: 80, mass: 1.2 },
          });

          // Floating animation bounded by the scale so it doesn't jump on spawn
          const safeScale = Math.min(1, Math.max(0, shapeScale));
          const floatY = Math.sin((frame + i * 30) / 20) * 30 * safeScale;
          const rotate = shape.r + (frame / 5) * (i % 2 === 0 ? 1 : -1);

          const left = width * shape.x;
          const top = height * shape.y;

          return (
            <div
              key={`shape-${i}`}
              style={{
                transition: "none",
                position: "absolute",
                left,
                top,
                transform: `translate(-50%, -50%) scale(${shapeScale * shape.s}) translateY(${floatY}px) rotate(${rotate}deg)`,
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
            >
              {shape.type === "star" ? (
                <Star
                  points={shape.points || 5}
                  innerRadius={30}
                  outerRadius={70}
                  fill={shapeColors[i % shapeColors.length]}
                  stroke="white"
                  strokeWidth={6}
                />
              ) : (
                <Circle
                  radius={45}
                  fill={shapeColors[i % shapeColors.length]}
                  stroke="white"
                  strokeWidth={6}
                />
              )}
            </div>
          );
        })}
      </AbsoluteFill>

      {/* Foreground Text Layer */}
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
        <div
          style={{
            display: "flex",
            flexWrap: "wrap",
            justifyContent: "center",
            alignItems: "center",
            alignContent: "center",
            gap: "20px 40px",
            width: "80%",
            textAlign: "center",
          }}
        >
          {words.map((word, i) => {
            const wordDelay = i * 6;
            const scale = spring({
              fps,
              frame: frame - wordDelay,
              config: { damping: 9, mass: 0.8, stiffness: 180 },
            });

            const safeScale = Math.min(1, Math.max(0, scale));
            
            // Alternating initial rotation for playfulness
            const staticRot = (i % 2 === 0 ? 1 : -1) * (3 + (i % 3) * 2);
            // Swing from an offset into the static rotation
            const currentRot = interpolate(scale, [0, 1], [staticRot - 30, staticRot]);
            
            // Gentle continuous floating after springing in
            const wordFloatY = Math.sin((frame + i * 40) / 15) * 12 * safeScale;

            return (
              <div
                key={`word-${i}`}
                style={{
                  transition: "none",
                  transform: `scale(${scale}) rotate(${currentRot}deg) translateY(${wordFloatY}px)`,
                  display: "inline-block",
                  padding: "15px",
                }}
              >
                <span
                  style={{
                    fontFamily: nunitoFamily,
                    fontWeight: 900, // Extrabold/Black for chunky look
                    color: wordColors[i % wordColors.length],
                    fontSize: `${width * 0.065}px`,
                    lineHeight: "1.2",
                    WebkitTextStroke: "8px white",
                    paintOrder: "stroke fill", // Helps keep the text body thick in supported browsers
                    textShadow: "6px 10px 0px rgba(0,0,0,0.15)",
                    display: "inline-block",
                  }}
                >
                  {word}
                </span>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default PreschoolTitle;